function validate([equations, values]) {
  if (!Array.isArray(equations) || equations.length < 1 || equations.length > 100) return 'equations needs 1 to 100 entries.';
  if (!Array.isArray(values) || values.length !== equations.length) return 'values must have one number per equation.';
  for (const pair of equations) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each equation is a pair of variable names.';
    if (pair.some(name => typeof name !== 'string' || !/^[a-z]{1,5}$/.test(name))) return 'Variable names are 1 to 5 lowercase letters.';
  }
  for (const v of values) {
    if (typeof v !== 'number' || !(v > 0) || v > 10) return 'Each value is above 0 and at most 10.';
    if (Math.abs(v * 100 - Math.round(v * 100)) > 1e-6) return 'Values have at most 2 decimal places.';
  }
  return null;
}

