function checkContradictions(equations, values) {
  const parent = new Map();
  const weight = new Map();

  const find = (node) => {
    if (!parent.has(node)) {
      parent.set(node, node);
      weight.set(node, 1);
    }
    const above = parent.get(node);
    if (above === node) {
      return node;
    }
    const root = find(above);
    weight.set(node, weight.get(node) * weight.get(above));
    parent.set(node, root);
    return root;
  };

  for (let i = 0; i < equations.length; i++) {
    const [a, b] = equations[i];
    const rootA = find(a);
    const rootB = find(b);
    if (rootA === rootB) {
      const implied = weight.get(a) / weight.get(b);
      if (Math.abs(implied - values[i]) >= 1e-5) {
        return true;
      }
    } else {
      parent.set(rootA, rootB);
      weight.set(rootA, values[i] * weight.get(b) / weight.get(a));
    }
  }
  return false;
}

