function checkContradictions(equations, values) {
  // Give each component's first variable the value 1, spread values by DFS, then test every equation.
  const graph = new Map();
  equations.forEach(([a, b], i) => {
    if (!graph.has(a)) graph.set(a, []);
    graph.get(a).push([b, 1 / values[i]]);
    if (!graph.has(b)) graph.set(b, []);
    graph.get(b).push([a, values[i]]);
  });
  const value = new Map();
  for (const start of graph.keys()) {
    if (value.has(start)) continue;
    value.set(start, 1);
    const stack = [start];
    while (stack.length) {
      const node = stack.pop();
      for (const [next, factor] of graph.get(node)) {
        if (value.has(next)) continue;
        value.set(next, value.get(node) * factor);
        stack.push(next);
      }
    }
  }
  return equations.some(([a, b], i) => Math.abs(value.get(a) / value.get(b) - values[i]) >= 1e-5);
}

