function generate(rand, size) {
  const large = size === 'large';
  const pick = (k) => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const count = large ? 30 + pick(40) : 2 + pick(4);
  const names = new Set();
  while (names.size < count) {
    const length = large ? 1 + pick(5) : 1 + pick(2);
    let name = '';
    for (let j = 0; j < length; j++) name += letters[pick(large ? 26 : 4)];
    names.add(name);
  }
  const vars = [...names];
  // Hidden values from {1, 2, 4, 5, 10}: every ratio lies in [0.1, 10] with at most 2 decimals.
  const scale = [1, 2, 4, 5, 10];
  const hidden = vars.map(() => scale[pick(scale.length)]);
  const m = large ? 100 : 1 + pick(7);
  const equations = [];
  const values = [];
  for (let i = 0; i < m; i++) {
    const x = pick(vars.length);
    const y = rand() < 0.05 ? x : pick(vars.length);
    equations.push([vars[x], vars[y]]);
    values.push(Math.round(hidden[x] / hidden[y] * 100) / 100);
  }
  // At most one equation is altered, so any contradiction is far larger than 10^-5.
  if (rand() < 0.6) {
    const i = pick(m);
    let changed;
    do changed = (1 + pick(1000)) / 100; while (changed === values[i]);
    values[i] = changed;
  }
  return [equations, values];
}
